/**
 * A sticky filter comparing against a variable that can never be bound in its scope can never accept a row: the compare
 * raises a type error for every candidate, FILTER drops error rows, and the generic fallback pays that as one thrown
 * exception per scanned row. Profiling the ELECTRICAL_GRID q7 bistability showed a slow-mode JVM spending 38% of its
 * samples in HotSpot's cross-frame exception dispatch for exactly this shape — ~112K throws per query execution,
 * forever, whenever C2 lost the inlining race between the throwing and the catching frame.
 * <p>
 * Binding analysis or the native entry predicate must instead prove the condition unable to accept a row and return an
 * empty result without opening a scan. That proof uses the actual execution input: a query with a supplied API
 * parameter or an in-scope VALUES binding must still evaluate its matching rows.
 */
public class LmdbNativeConstantFalseFilterTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI transformerType = vf.createIRI(EX, "Transformer");
			IRI feeds = vf.createIRI(EX, "feeds");
			IRI hasMeter = vf.createIRI(EX, "hasMeter");
			IRI measures = vf.createIRI(EX, "measures");
			conn.begin();
			for (int i = 0; i < 40; i++) {
				IRI transformer = vf.createIRI(EX, "transformer" + i);
				IRI substation = vf.createIRI(EX, "substation" + (i % 5));
				IRI meter = vf.createIRI(EX, "meter" + i);
				conn.add(transformer, org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, transformerType);
				conn.add(transformer, feeds, substation);
				conn.add(transformer, hasMeter, meter);
				// meters measure loads; one meter "measures" substation0 so the VALUES variant has a real match
				conn.add(meter, measures, i == 7 ? vf.createIRI(EX, "substation0") : vf.createIRI(EX, "load" + i));
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		System.clearProperty(NATIVE_FLAG);
		repository.shutDown();
	}

	@Test
	public void outOfScopeCompareShortCircuitsToEmptyWithoutScanning() {
		// ?substation never appears outside the filter: the compare errors for every row, so the fragment is
		// provably empty and the scan must not run.
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?meter ?load WHERE { ?meter ex:measures ?load . FILTER(?load = ?substation) }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
			String explanation = prepared.explain(Explanation.Level.Telemetry).toString();

			assertThat(rows(query)).isEmpty();
			try (var result = prepared.evaluate()) {
				assertThat(result.getBindingNames()).containsExactly("meter", "load");
				assertThat(result.hasNext()).isFalse();
			}
			assertThat(explanation)
					.as("a filter proven unable to accept any row must short-circuit the fragment instead of "
							+ "scanning and erroring once per row")
					.contains("NativeRows(arg=Empty", "NO_STATEMENT_ACCESS_REACHED");
		}
	}

	@Test
	public void minusArmWithOutOfScopeCompareMatchesGeneric() {
		// The ELECTRICAL_GRID q7 shape in miniature. The MINUS arm's filter compares against ?substation, which is
		// out of scope inside the arm; the arm is empty and MINUS removes nothing.
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?transformer) AS ?count) WHERE {\n"
				+ "  ?transformer a ex:Transformer ; ex:feeds ?substation .\n"
				+ "  FILTER EXISTS { ?transformer ex:hasMeter ?meter . }\n"
				+ "  MINUS { ?meter ex:measures ?load . FILTER(?load = ?substation) }\n"
				+ "}";
		assertThat(rows(query)).isEqualTo(genericRows(query));
	}

	@Test
	public void inScopeCompareStillEvaluatesTheFilter() {
		// Same textual filter, but VALUES puts ?substation in scope with a binding: the filter is not constant
		// false and must keep the one genuinely matching row.
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?meter ?load WHERE {\n"
				+ "  VALUES ?substation { ex:substation0 }\n"
				+ "  ?meter ex:measures ?load . FILTER(?load = ?substation)\n"
				+ "}";
		List<String> generic = genericRows(query);
		assertThat(generic).hasSize(1);
		assertThat(rows(query)).isEqualTo(generic);
	}

	@Test
	public void apiBoundCompareStillEvaluatesTheFilter() {
		String query = "PREFIX ex: <" + EX + "> "
				+ "SELECT ?meter ?load WHERE { ?meter ex:measures ?load . FILTER(?load = ?substation) }";
		try (SailRepositoryConnection connection = repository.getConnection()) {
			var prepared = connection.prepareTupleQuery(query);
			prepared.setBinding("substation", connection.getValueFactory().createIRI(EX, "substation0"));
			try (var result = prepared.evaluate()) {
				assertThat(QueryResults.asList(result)).singleElement()
						.satisfies(row -> assertThat(row.getValue("load"))
								.isEqualTo(connection.getValueFactory().createIRI(EX, "substation0")));
			}
		}
	}

	private List<String> genericRows(String query) {
		System.setProperty(NATIVE_FLAG, "false");
		try {
			return rows(query);
		} finally {
			System.clearProperty(NATIVE_FLAG);
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate())
					.stream()
					.map(LmdbNativeConstantFalseFilterTest::render)
					.sorted()
					.collect(Collectors.toList());
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining(","));
	}
}
